package org.freecad.mobilelab;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.concurrent.*;
import org.qtproject.qt.android.MobileCoreBootstrap;

/** Isolated upstream App editor. Part and geometry workbenches come later. */
public final class CoreDocumentActivity extends Activity {
    private static final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final java.util.ArrayList<Button> buttons=new java.util.ArrayList<>();
    private TextView report,status,pythonReport;private EditText command;private boolean busy,destroyed;
    private JSONObject state;private File documents;private String exportFile,exportMacro;
    @Override public void onCreate(Bundle saved){
        super.onCreate(saved);if(saved!=null){exportFile=saved.getString("export_file");exportMacro=saved.getString("export_macro");}Diagnostics.stage(this,"Upstream document lab UI created");
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(20,20,20,20);root.setBackgroundColor(0xff111820);
        
        root.addView(text("FREECAD / DOCUMENT LAB",20));
        root.addView(text("Upstream App 1.1.4 · properties, expressions, transactions\nGeometry workbenches are still being ported.",13));
        status=text("Preparing private document runtime…",13);root.addView(status);
        row(root,new String[]{"New","Objects","Property"},new Runnable[]{this::newDocument,this::objectMenu,this::propertyMenu});
        row(root,new String[]{"Set / formula","Undo","Redo"},new Runnable[]{this::editMenu,()->send("undo"),()->send("redo")});
        row(root,new String[]{"Save FCStd","Open FCStd","Documents"},new Runnable[]{this::saveDialog,this::openMenu,this::documentsMenu});
        row(root,new String[]{"Begin edit","Commit","Cancel edit"},new Runnable[]{()->send("begin"),()->send("commit"),()->send("abort")});
        row(root,new String[]{"Python","Macros","API","Script feature"},new Runnable[]{this::consoleDialog,this::macroMenu,this::apiDialog,this::proxyDialog});
        report=text("",13);report.setTextIsSelectable(true);root.addView(report);pythonReport=text("",13);pythonReport.setTextIsSelectable(true);root.addView(pythonReport);
        LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setBackgroundColor(0xff111820);page.setOnApplyWindowInsetsListener((v,i)->{page.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});ScrollView body=new ScrollView(this);body.addView(root);page.addView(body,new LinearLayout.LayoutParams(-1,0,1));
        command=new EditText(this);command.setTextColor(0xffedf3f8);command.setHintTextColor(0xff99aabe);command.setHint("Command · Set Source.Width 2 cm");command.setTextSize(13);command.setSingleLine(true);page.addView(command);
        row(page,new String[]{"Run command","Help","Restart lab","Recovery"},new Runnable[]{()->{String input=command.getText().toString();if(!input.trim().isEmpty()){job(()->request(CoreCommandLine.parse(input)));}},this::help,this::restartLab,()->startActivity(new Intent(this,StartupActivity.class).putExtra("diagnostics_only",true))});
        setContentView(page);
        // Register the official Qt Java context before QtCore's JNI_OnLoad.
        try{MobileCoreBootstrap.prepare(this);}catch(Throwable e){error(e);setEnabled(false);return;}
        job(()->{
            File home=CoreAssets.install(this);documents=new File(home.getParentFile(),"documents");
            Diagnostics.stage(this,"Loading isolated upstream document bridge");System.loadLibrary("freecad_document_bridge");
            CoreNative.initialize(home.getAbsolutePath(),new File(home,"scripts").getAbsolutePath(),home.getParentFile().getAbsolutePath());
            return request("{\"op\":\"state\"}");
        });
    }
    private TextView text(String value,int size){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(0xffedf3f8);return view;}
    private void row(LinearLayout root,String[] labels,Runnable[] actions){LinearLayout row=new LinearLayout(this);for(int i=0;i<labels.length;i++){Button b=new Button(this);b.setText(labels[i]);b.setAllCaps(false);final Runnable action=actions[i];b.setOnClickListener(v->{if(!busy)action.run();});buttons.add(b);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}root.addView(row);}
    private void setEnabled(boolean value){for(Button b:buttons)b.setEnabled(value||b.getText().toString().equals("Recovery")||b.getText().toString().equals("Help")||b.getText().toString().equals("Restart lab"));command.setEnabled(value);}
    private void restartLab(){new AlertDialog.Builder(this).setTitle("Restart document lab?").setMessage("Unsaved lab documents will close. Saved FCStd files and macros are kept. The CAD workspace stays in its separate process.").setNegativeButton("Cancel",null).setPositiveButton("Restart",(d,w)->{startActivity(new Intent(this,StartupActivity.class).putExtra("diagnostics_only",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));android.os.Process.killProcess(android.os.Process.myPid());}).show();}
    private interface Task{JSONObject run()throws Exception;}
    private void job(Task task){if(busy)return;busy=true;setEnabled(false);status.setText("Working…");worker.execute(()->{try{JSONObject next=task.run();runOnUiThread(()->{if(destroyed)return;busy=false;setEnabled(true);state=next;render();});}catch(Throwable e){Diagnostics.error(this,"Upstream document operation",e);runOnUiThread(()->{if(destroyed)return;busy=false;setEnabled(true);error(e);});}});}
    private JSONObject request(String text)throws Exception{JSONObject result=new JSONObject(CoreNative.request(text));if(!result.getBoolean("ok"))throw new IOException(result.getString("error"));return result.getJSONObject("state");}
    private JSONObject request(JSONObject json)throws Exception{return request(json.toString());}
    private void send(String action){job(()->request(new JSONObject().put("op",action)));}
    private void edit(JSONObject edit){job(()->request(new JSONObject().put("op","batch").put("edits",new JSONArray().put(edit))));}
    private void render(){try{renderPython();StringBuilder b=new StringBuilder();JSONObject doc=state.optJSONObject("document");status.setText(state.optBoolean("transaction")?"Transaction open · commit or cancel to finish":"Ready · changes remain editable");if(doc==null){report.setText("Create a document, or open a supported FCStd metadata document.");return;}b.append(doc.getString("label")).append("\nUndo: ").append(doc.getInt("undo")).append(" · Redo: ").append(doc.getInt("redo")).append("\n\n");JSONArray objects=doc.getJSONArray("objects");for(int i=0;i<objects.length();i++){JSONObject o=objects.getJSONObject(i);b.append(o.getString("name")).append(" · ").append(o.getString("label")).append("\n").append(o.getString("type")).append("\n");JSONArray props=o.getJSONArray("properties");for(int j=0;j<props.length();j++){JSONObject p=props.getJSONObject(j);Object value=p.get("value");if(value instanceof JSONObject&&((JSONObject)value).has("text"))value=((JSONObject)value).getString("text");b.append("  ").append(p.getString("name")).append(" = ").append(value).append("\n");}b.append("Expressions: ").append(o.getJSONArray("expressions")).append("\nReferences: ").append(o.getJSONArray("dependencies")).append("\n\n");}report.setText(b.toString());}catch(Exception e){error(e);}}
    private void error(Throwable e){status.setText("Operation failed");new AlertDialog.Builder(this).setTitle("Document operation").setMessage(e.getMessage()==null?e.toString():e.getMessage()).setPositiveButton("OK",null).show();}
    private interface Fields{void accept(String[] values)throws Exception;}
    private void fields(String title,String[] labels,String[] defaults,Fields callback){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,10,24,10);EditText[] inputs=new EditText[labels.length];for(int i=0;i<labels.length;i++){root.addView(text(labels[i],13));EditText input=new EditText(this);input.setTextColor(0xffedf3f8);input.setText(defaults[i]);input.setSingleLine(true);inputs[i]=input;root.addView(input);}ScrollView scroll=new ScrollView(this);scroll.addView(root);new AlertDialog.Builder(this).setTitle(title).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{String[] values=new String[inputs.length];for(int i=0;i<inputs.length;i++)values[i]=inputs[i].getText().toString();try{callback.accept(values);}catch(Exception e){error(e);}}).show();}
    private String firstObject(){try{return state.getJSONObject("document").getJSONArray("objects").getJSONObject(0).getString("name");}catch(Exception e){return "Feature";}}
    private void newDocument(){fields("New upstream document",new String[]{"Name"},new String[]{"MobileDocument"},v->job(()->request(new JSONObject().put("op","new").put("name",v[0]))));}
    private void objectMenu(){new AlertDialog.Builder(this).setTitle("Objects").setItems(new String[]{"Feature","Group","Linked instance","Variable set","Remove object","Add to group","Set link target"},(d,w)->{if(w<4){String[] types={"App::FeaturePython","App::DocumentObjectGroup","App::Link","App::VarSet"};fields("Add "+types[w],new String[]{"Name","Label"},new String[]{"Feature","Feature"},v->edit(new JSONObject().put("op","add").put("type",types[w]).put("name",v[0]).put("label",v[1])));}else if(w==4)fields("Remove object",new String[]{"Name"},new String[]{firstObject()},v->edit(new JSONObject().put("op","remove").put("object",v[0])));else if(w==5)fields("Group membership",new String[]{"Group","Object"},new String[]{"Group",firstObject()},v->edit(new JSONObject().put("op","group").put("group",v[0]).put("object",v[1])));else fields("Linked instance",new String[]{"Link object","Target object"},new String[]{"Instance",firstObject()},v->edit(new JSONObject().put("op","link").put("object",v[0]).put("target",v[1])));}).show();}
    private void propertyMenu(){String[] kinds={"Length","Angle","Area","Volume","Float","Integer","String","Bool","Link"};new AlertDialog.Builder(this).setTitle("Add property").setItems(kinds,(d,w)->fields("Add "+kinds[w],new String[]{"Object","Property"},new String[]{firstObject(),"Width"},v->edit(new JSONObject().put("op","property").put("object",v[0]).put("name",v[1]).put("type","App::Property"+kinds[w])))).show();}
    private void editMenu(){new AlertDialog.Builder(this).setTitle("Edit property").setItems(new String[]{"Set value","Set expression","Clear expression"},(d,w)->fields(w==0?"Set property":"Expression",new String[]{"Object","Property",w==0?"Value (e.g. 2 cm)":"Expression (e.g. Source.Width * 2)"},new String[]{firstObject(),"Width",w==0?"20 mm":""},v->{JSONObject edit=new JSONObject().put("op",w==0?"set":"expression").put("object",v[0]).put("property",v[1]);if(w==0){edit.put("value",v[2]);}else edit.put("expression",w==2?"":v[2]);edit(edit);})).show();}
    private void saveDialog(){fields("Save native FCStd",new String[]{"Filename"},new String[]{"MobileDocument.FCStd"},v->job(()->{JSONObject next=request(new JSONObject().put("op","save").put("file",v[0]));exportFile=v[0];runOnUiThread(()->{if(destroyed)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,exportFile);startActivityForResult(i,82);});return next;}));}
    private void openMenu(){new AlertDialog.Builder(this).setTitle("Open FCStd").setItems(new String[]{"Import from files","Open private saved file"},(d,w)->{if(w==0){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,81);}else fields("Private document",new String[]{"Filename"},new String[]{"MobileDocument.FCStd"},v->job(()->request(new JSONObject().put("op","open").put("file",v[0]))));}).show();}
    private void documentsMenu(){try{JSONArray list=state.getJSONArray("documents");String[] names=new String[list.length()+1];for(int i=0;i<list.length();i++)names[i]=list.getString(i);names[list.length()]="Close active document";new AlertDialog.Builder(this).setTitle("Documents").setItems(names,(d,w)->{if(w==names.length-1)send("close");else job(()->request(new JSONObject().put("op","activate").put("name",names[w])));}).show();}catch(Exception e){error(e);}}
    private void help(){new AlertDialog.Builder(this).setTitle("Document commands").setMessage(CoreCommandLine.HELP+"\n\nPython print(App.Version())\nRunMacro MyMacro.py\nApi App.Vector\nProxy Scaled Source.Width 2\n\nPython console, saved macros, command recording and the portable QuantityDriver proxy are available from the buttons. Python tracing has a two-second budget; native calls may take longer. The API browser covers available App/Base bindings. Arbitrary addon proxy classes and Part/Gui bindings remain pending.\n\nPart, Sketcher, and PartDesign documents need their workbench ports first.").setPositiveButton("OK",null).show();}

    private void renderPython()throws Exception{
        JSONObject python=state.optJSONObject("python");if(python==null)return;StringBuilder b=new StringBuilder();JSONObject console=python.optJSONObject("console");
        if(python.optBoolean("recording"))b.append("Recording document commands…\n");
        if(console!=null){b.append(console.optString("output"));if(!console.optString("error").isEmpty())b.append("\n").append(console.optString("error"));}
        JSONObject api=python.optJSONObject("api");if(api!=null)b.append("\nAPI: ").append(api.getString("target")).append("\n").append(api.optString("doc")).append("\n").append(api.getJSONArray("members")).append("\n");
        b.append("\nSaved macros: ").append(python.getJSONArray("macros"));pythonReport.setText(b.toString());
        if(state.has("macro_source")){String name=state.getString("macro_name"),source=state.getString("macro_source");state.remove("macro_source");macroEditor(name,source);}
    }
    private interface CodeAction{void apply(String code)throws Exception;}
    private void codeEditor(String title,String initial,CodeAction action){EditText input=new EditText(this);input.setTextColor(0xffedf3f8);input.setTextSize(13);input.setTypeface(android.graphics.Typeface.MONOSPACE);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setMinLines(5);input.setMaxLines(12);input.setText(initial);ScrollView scroll=new ScrollView(this);scroll.addView(input);new AlertDialog.Builder(this).setTitle(title).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{try{action.apply(input.getText().toString());}catch(Exception e){error(e);}}).show();}
    private void consoleDialog(){String previous=getSharedPreferences("core_python",MODE_PRIVATE).getString("last","print(App.Version())");codeEditor("Python console · App / FreeCAD",previous,code->{getSharedPreferences("core_python",MODE_PRIVATE).edit().putString("last",code).apply();job(()->request(new JSONObject().put("op","python").put("code",code)));});}
    private void apiDialog(){fields("Available Python API",new String[]{"Target"},new String[]{"App.Vector"},v->job(()->request(new JSONObject().put("op","api").put("target",v[0]))));}
    private void proxyDialog(){fields("Scripted QuantityDriver",new String[]{"Name","Source object","Length property","Factor"},new String[]{"Scaled",firstObject(),"Width","2"},v->edit(new JSONObject().put("op","proxy").put("name",v[0]).put("source",v[1]).put("property",v[2]).put("factor",Double.parseDouble(v[3]))));}
    private void macroEditor(String name,String code){codeEditor("Edit "+name,code,source->job(()->request(new JSONObject().put("op","macro_save").put("name",name).put("code",source))));}
    private void macroMenu(){new AlertDialog.Builder(this).setTitle("Python macros").setItems(new String[]{"New macro","Open / edit macro","Run macro","Record document commands","Save recording","Import Python file","Export Python file"},(d,w)->{if(w==0)fields("New macro",new String[]{"Filename"},new String[]{"MyMacro.py"},v->macroEditor(v[0],"import FreeCAD as App\nprint(App.Version())\n"));else if(w==1||w==2)fields(w==1?"Edit macro":"Run macro",new String[]{"Filename"},new String[]{"MyMacro.py"},v->job(()->request(new JSONObject().put("op",w==1?"macro_read":"macro_run").put("name",v[0]))));else if(w==3)send("record_start");else if(w==4)fields("Save recording",new String[]{"Filename"},new String[]{"Recorded.py"},v->job(()->request(new JSONObject().put("op","record_stop").put("name",v[0]))));else if(w==5){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,83);}else fields("Export macro",new String[]{"Filename"},new String[]{"MyMacro.py"},v->{exportMacro=v[0];if(!exportMacro.matches("[A-Za-z_][A-Za-z_0-9-]{0,79}\\.py"))throw new IOException("Use a plain .py filename");Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/x-python");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,exportMacro);startActivityForResult(i,84);});}).show();}
    @Override protected void onSaveInstanceState(Bundle state){state.putString("export_file",exportFile);state.putString("export_macro",exportMacro);super.onSaveInstanceState(state);}

    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(code==83){job(()->{String name="Imported-"+System.currentTimeMillis()+".py";java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open macro");copy(in,bytes,65536);}String source=java.nio.charset.StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();if(source.startsWith("\ufeff"))source=source.substring(1);return request(new JSONObject().put("op","macro_save").put("name",name).put("code",source));});return;}if(code==84){final String name=exportMacro;job(()->{JSONObject loaded=request(new JSONObject().put("op","macro_read").put("name",name));try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open macro output");out.write(loaded.getString("macro_source").getBytes(java.nio.charset.StandardCharsets.UTF_8));}return request("{}");});return;}if(code==81)job(()->{String name="Imported-"+System.currentTimeMillis()+".FCStd";File file=new File(documents,name);try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("Cannot open input");copy(in,out,128L*1024*1024);}catch(Exception e){file.delete();throw e;}return request(new JSONObject().put("op","open").put("file",name));});else if(code==82){final String name=exportFile;job(()->{try(InputStream in=new FileInputStream(new File(documents,name));OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open output");copy(in,out,128L*1024*1024);}return request("{}");});}}
    private static void copy(InputStream in,OutputStream out,long maximum)throws IOException{byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>maximum)throw new IOException("File exceeds "+maximum+" bytes");out.write(buffer,0,n);}}
    @Override protected void onDestroy(){destroyed=true;super.onDestroy();}
}
